INSERT OR IGNORE INTO service_categories (id, slug, name_fr, name_ar, description_fr, cover_image, display_order, is_active) VALUES
('cat_mariages', 'mariages', 'Mariages', 'حفلات الزفاف', 'Conception intégrale, scénographie florale et coordination le jour J pour des réceptions d’exception à Casablanca.', '/src/assets/images/wedding_garden_ceremony_1795343964563.jpg', 1, 1),
('cat_fiancailles', 'fiancailles', 'Fiançailles', 'حفلات الخطوبة', 'Célébrations intimes ou familiales mêlant élégance contemporaine et accueil marocain chaleureux.', '/src/assets/images/hero_casablanca_gala_1795343965521.jpg', 2, 1),
('cat_anniversaires', 'anniversaires', 'Anniversaires', 'أعياد الميلاد', 'Décors sur mesure, tables gourmandes et ambiance musicale pour marquer chaque étape importante.', '/src/assets/images/catering_floral_table_1795343966400.jpg', 3, 1),
('cat_corporate', 'evenements-professionnels', 'Événements professionnels', 'الفعاليات المهنية', 'Conférences, séminaires, lancements de produits, team building et dîners de gala d’entreprise à Casablanca.', '/src/assets/images/corporate_gala_casablanca_1795343965280.jpg', 4, 1),
('cat_ceremonies', 'ceremonies-marocaines', 'Cérémonies marocaines', 'الطقوس المغربية', 'Soirées henné, salons traditionnels raffinés, amariya et mise en valeur du patrimoine marocain.', '/src/assets/images/moroccan_henna_salon_1795343965226.jpg', 5, 1),
('cat_privees', 'fetes-privees', 'Fêtes privées', 'الحفلات الخاصة', 'Baby showers, remises de diplômes, réceptions familiales et soirées privées en villa ou salon.', '/src/assets/images/hero_casablanca_gala_1795343965521.jpg', 6, 1);

INSERT OR IGNORE INTO services (id, category_id, slug, name_fr, name_ar, short_description_fr, description_fr, benefits_json, included_json, options_json, cover_image, starting_price_mad, price_is_example, is_available, display_order) VALUES
('srv_wedding', 'cat_mariages', 'organisation-mariage', 'Organisation complète de mariage', 'تنظيم حفل الزفاف بالكامل', 'Pilotage intégral de votre mariage à Casablanca, de la conception du thème à la coordination du jour J.', 'Notre équipe vous accompagne étape par étape pour imaginer un mariage à votre image : sélection du lieu, choix des prestataires, planification budgétaire, rétroplanning et présence dédiée le jour de la réception.', '["Interlocuteur unique dédié tout au long des préparatifs","Maîtrise des prestataires fiables à Casablanca et environs","Gestion sereine du timing et des imprévus le jour J"]', '["Étude de concept et planche d’inspiration personnalisée","Repérage et sélection du lieu de réception","Coordination complète des prestataires et du déroulé","Présence de coordinateurs sur site le jour de l’événement"]', '["Gestion des invitations et confirmations (RSVP)","Accueil et logistique des invités internationaux","Cérémonie de henné coordonnée la veille"]', '/src/assets/images/wedding_garden_ceremony_1795343964563.jpg', NULL, 0, 1, 1),
('srv_engagement', 'cat_fiancailles', 'organisation-fiancailles', 'Organisation de fiançailles', 'تنظيم حفل الخطوبة', 'Une réception élégante et intimiste pour célébrer votre engagement auprès de vos proches.', 'Nous concevons des cérémonies de fiançailles harmonieuses, à domicile, en villa privée ou dans un salon de réception à Casablanca.', '["Scénographie adaptée aux espaces privés ou salons","Coordination discrète et respectueuse des traditions familiales","Budget maîtrisé avec devis transparent"]', '["Décoration florale de l’espace d’honneur","Mise en table et art de recevoir","Coordination traiteur, pâtisserie et animation douce"]', '["Reportage photo & vidéo","Ensemble musical traditionnel ou acoustique","Coin photo sur mesure"]', '/src/assets/images/hero_casablanca_gala_1795343965521.jpg', NULL, 0, 1, 2),
('srv_birthday', 'cat_anniversaires', 'organisation-anniversaire', 'Organisation d’anniversaire & fêtes privées', 'تنظيم أعياد الميلاد والحفلات الخاصة', 'Anniversaires, baby showers et remises de diplômes mis en scène avec créativité et convivialité.', 'Nous orchestrons décor, buffet, gâteau signature et ambiance musicale pour vos fêtes familiales ou privées à Casablanca.', '["Thématique et palette chromatique entièrement personnalisées","Formules modulables selon le nombre d’invités","Installation et démontage clé en main"]', '["Direction artistique et habillage du lieu","Installation du mobilier et centres de table","Coordination de la réception"]', '["Sweet table et gâteau d’événement sur mesure","DJ et sonorisation d’ambiance","Photographe événementiel"]', '/src/assets/images/catering_floral_table_1795343966400.jpg', 4500, 1, 1, 3),
('srv_corporate', 'cat_corporate', 'evenements-professionnels', 'Événements professionnels, séminaires & team building', 'تنظيم المؤتمرات وفعاليات الشركات', 'Conférences, lancements de marque, séminaires et galas corporate avec rigueur technique.', 'EVENT PRO accompagne les entreprises casablancaises dans l’organisation de leurs plénières, pauses gastronomiques, team building et dîners de gala.', '["Respect strict de votre charte graphique et protocole d’entreprise","Équipement audiovisuel et scénique fiable","Facturation claire en MAD et devis détaillé par poste"]', '["Repérage de salle de conférence ou hôtel partenaire","Régie technique son, microphonie et projection","Gestion des pauses café, déjeuners ou dîners de gala"]', '["Captation vidéo multicaméra","Activités de cohésion d’équipe","Hôtesses d’accueil et signalétique"]', '/src/assets/images/corporate_gala_casablanca_1795343965280.jpg', NULL, 0, 1, 4),
('srv_moroccan', 'cat_ceremonies', 'ceremonies-marocaines', 'Cérémonies marocaines & soirées henné', 'الطقوس المغربية وليلة الحناء', 'Mise en scène authentique et contemporaine des traditions marocaines avec soin artisanal.', 'Nous sublimons la soirée du henné et les cérémonies traditionnelles grâce à un mobilier marocain raffiné, des lanternes en laiton ciselé et des compositions florales blanches.', '["Alliance harmonieuse entre artisanat marocain et sobriété contemporaine","Respect des rituels familiaux","Sélection de salons et espaces adaptés à Casablanca"]', '["Aménagement du salon traditionnel et coin henné","Éclairage chaud par lanternes et bougies","Coordination de l’accueil et du service du thé"]', '["Orchestre andalou, issawa ou dakka marrakchia","Plateau de pâtisseries marocaines fines","Amariya et habillage d’entrée"]', '/src/assets/images/moroccan_henna_salon_1795343965226.jpg', NULL, 0, 1, 5),
('srv_decoration', 'cat_mariages', 'decoration-florale', 'Décoration événementielle & art floral', 'الديكور وتنسيق الزهور', 'Scénographie sur mesure, arches florales, tables d’honneur et mise en lumière poétique.', 'Nos designers floraux et décorateurs conçoivent des ambiances uniques en fleurs fraîches, textiles nobles, verrerie et bougeoirs.', '["Palette de couleurs étudiée selon la lumière du lieu","Fleurs fraîches sélectionnées","Cohérence visuelle de l’entrée aux tables"]', '["Proposition esthétique et plan de table décoratif","Centres de table floraux et chemin de table","Installation complète et reprise en fin d’événement"]', '["Arche cérémonielle grand format","Mur floral personnalisé","Papeterie de table"]', '/src/assets/images/wedding_garden_ceremony_1795343964563.jpg', 6000, 1, 1, 6),
('srv_catering', 'cat_mariages', 'traiteur-buffet', 'Traiteur & buffet gastronomique', 'خدمات الضيافة والبوفيه', 'Cuisine marocaine raffinée, gastronomie internationale et cocktails dînatoires soignés.', 'Des pièces cocktails délicates aux dîners de gala servis à l’assiette, nos brigades assurent une expérience culinaire irréprochable.', '["Menus sur mesure adaptés aux convives","Service en salle attentif","Dégustation préalable possible"]', '["Élaboration du menu (cocktail, buffet ou dîner assis)","Vaisselle, verrerie et nappage","Personnel de cuisine et maîtres d’hôtel"]', '["Atelier thé à la menthe et pâtisseries marocaines","Bar à mocktails et jus frais","Wedding cake artisanal"]', '/src/assets/images/catering_floral_table_1795343966400.jpg', NULL, 0, 1, 7),
('srv_venues', 'cat_corporate', 'location-salles', 'Location de salles & lieux d’exception', 'كراء القاعات والفضاءات', 'Accès privilégié à des villas, jardins, riads et salles de réception à Casablanca.', 'Nous vous aidons à identifier et réserver le cadre idéal à Anfa, Bouskoura, Ain Diab ou Dar Bouazza selon votre capacité et votre budget.', '["Sélection ciblée selon capacité et accès","Visites accompagnées avec analyse technique","Vérification des contraintes logistiques"]', '["Proposition de lieux disponibles à votre date","Organisation des visites de repérage","Coordination technique avec le site"]', '["Tente caïdale ou structure cristal","Service voiturier et accueil sécurité","Groupe électrogène de secours"]', '/src/assets/images/hero_casablanca_gala_1795343965521.jpg', NULL, 0, 1, 8),
('srv_photo', 'cat_mariages', 'photographie-videographie', 'Photographie & vidéographie', 'التصوير الفوتوغرافي والفيديو', 'Immortalisation sensible et cinématographique de chaque regard, détail et émotion.', 'Nos photographes et vidéastes capturent votre événement avec discrétion et sens esthétique.', '["Style éditorial naturel","Matériel plein format et audio net","Livraison rapide d’un premier aperçu"]', '["Couverture photographique sur la durée convenue","Retouche colorimétrique homogène","Galerie privée en ligne haute résolution"]', '["Film cinématographique 4K","Prises de vues par drone","Album imprimé relié lin"]', '/src/assets/images/wedding_garden_ceremony_1795343964563.jpg', 5500, 1, 1, 9),
('srv_sound_dj', 'cat_privees', 'sonorisation-eclairage-dj', 'Sonorisation, éclairage & animation DJ', 'الصوتيات والإضاءة وتنشيط الدي جي', 'Acoustique claire, mise en lumière architecturale et programmation musicale sur mesure.', 'Sonorisation professionnelle, éclairage architectural chaud, régie DJ et ensembles musicaux adaptés à votre public.', '["Matériel discret et câblage dissimulé","Répertoire chaabi, oriental et international","Technicien présent sur place"]', '["Système de sonorisation adapté à la salle","Microphones sans fil pour discours","Éclairage d’ambiance et piste de danse"]', '["DJ généraliste ou spécialisé","Violoniste, saxophoniste ou orchestre","Éclairage architectural extérieur"]', '/src/assets/images/corporate_gala_casablanca_1795343965280.jpg', 4000, 1, 1, 10),
('srv_furniture', 'cat_privees', 'mobilier-equipement', 'Location de mobilier & équipements événementiels', 'كراء الأثاث ومعدات الحفلات', 'Chaises de réception, tables banquet, salons lounge, nappages et accessoires de scène.', 'Mobilier entretenu, livré et installé selon votre plan de salle à Casablanca et environs.', '["Mobilier entretenu et prêt à l’emploi","Cohérence esthétique avec le décor","Livraison et reprise incluses"]', '["Transport aller-retour sur le lieu","Installation selon plan d’implantation","Reprise après événement"]', '["Nappage en lin ou coton épais","Chauffages de terrasse","Podium et piste de danse modulable"]', '/src/assets/images/moroccan_henna_salon_1795343965226.jpg', NULL, 0, 1, 11);

INSERT OR IGNORE INTO gallery_images (id, title, caption, category, image_url, display_order, is_featured) VALUES
('gal_1', 'Dîner aux chandelles sous les arcades', 'Réception de mariage en cour intérieure à Casablanca — tables impériales, roses blanches et lanternes en laiton.', 'Mariages', '/src/assets/images/hero_casablanca_gala_1795343965521.jpg', 1, 1),
('gal_2', 'Cérémonie laïque dans les jardins d’Anfa', 'Arche florale d’orchidées et roses crème, allée en travertine et assises en bois clair.', 'Mariages', '/src/assets/images/wedding_garden_ceremony_1795343964563.jpg', 2, 1),
('gal_3', 'Salon traditionnel de cérémonie du henné', 'Zellige contemporain, lanternes ciselées, broderies ivoire et compositions florales blanches.', 'Cérémonies marocaines', '/src/assets/images/moroccan_henna_salon_1795343965226.jpg', 3, 1),
('gal_4', 'Gala & forum des dirigeants à Casablanca', 'Configuration conférence et dîner assis avec éclairage architectural et scénographie épurée.', 'Événements professionnels', '/src/assets/images/corporate_gala_casablanca_1795343965280.jpg', 4, 1),
('gal_5', 'Art de la table & cocktail gastronomique', 'Présentoirs en travertine, verrerie cristalline et bouquets d’inspiration jardin.', 'Traiteur', '/src/assets/images/catering_floral_table_1795343966400.jpg', 5, 1),
('gal_6', 'Composition florale & bougeoirs en laiton', 'Roses de jardin ivoire, feuillage d’olivier et cristallerie fine sur nappe en lin.', 'Décoration', '/src/assets/images/floral_arch_decor_1795344660354.jpg', 6, 1),
('gal_7', 'Réception privée en villa à Bouskoura', 'Ambiance nocturne chaleureuse pour anniversaire majeur et fête familiale.', 'Anniversaires', '/src/assets/images/hero_casablanca_gala_1795343965521.jpg', 7, 0),
('gal_8', 'Soirée privée sous les arcades d’Anfa', 'Terrasse illuminée au crépuscule avec salons lounge et lanternes en laiton.', 'Fêtes privées', '/src/assets/images/evening_soiree_cocktails_1795344660836.jpg', 8, 1);

INSERT OR IGNORE INTO testimonials (id, client_name, event_type, city, quote_text, is_demo, is_approved) VALUES
('test_1', 'Salma & Youssef B.', 'Mariage complet — Casablanca', 'Casablanca', 'Témoignage de démonstration : De la visite des jardins jusqu’au dernier morceau de musique, l’équipe EVENT PRO a orchestré chaque prestataire avec calme et précision.', 1, 1),
('test_2', 'Direction Communication — Groupe financier (Casablanca)', 'Séminaire annuel & dîner de gala', 'Casablanca', 'Témoignage de démonstration : Devis détaillé dès le premier échange, régie audiovisuelle irréprochable pour nos 180 collaborateurs et dîner de gala livré à la minute près.', 1, 1),
('test_3', 'Kenza E.', 'Cérémonie de fiançailles & henné', 'Dar Bouazza', 'Témoignage de démonstration : L’équilibre entre l’artisanat marocain et la sobriété des fleurs blanches correspondait exactement à ce que nous imaginions.', 1, 1);
